#[test]
fn w333_first_call_dates_live_index() {
    use crate::{
        contracts::OperationOwner,
        core::{ToolCallRecordPhase, ToolCallRecorded, ToolResultRecorded, TurnOpened},
        domain::{AgentTask, ExecutionId, SessionId, ThreadId, ToolCallResolution, ToolResult, TurnId},
    };
    use serde_json::json;
    let (session, thread, turn, exec)=(SessionId::from_u128(1), ThreadId::from_u128(2),
        TurnId::from_u128(3), ExecutionId::from_uuid(uuid::Uuid::from_u128(4)));
    for n in [0,1,256,4096] {
        for repeats in [false,true] {
            let mut records=Vec::new();
            let mut push=|entry, timestamp_ms| {
                records.push(JournalRecord{schema_version:JOURNAL_SCHEMA_VERSION,record_id:new_record_id(),
                    session_seq:records.len() as u64+1,timestamp_ms,session_id:session,execution_id:Some(exec),
                    thread_id:Some(thread),turn_id:Some(turn),entry});
            };
            push(JournalEntry::TurnOpened(TurnOpened{
                intent:None,task:AgentTask::new("fixture","/synthetic/workspace".into()),
                base_history_revision:0,module_epoch:0,config_snapshot:json!({}),
            }),100);
            let mut ids=Vec::new();
            for i in 0..n {
                let call=ToolCall::new(format!("fixture-workflow-call-{i:04}"),"fixture",json!({}));
                ids.push(call.id.clone());
                push(JournalEntry::ToolCallRecorded(ToolCallRecorded{call:call.clone(),
                    phase:ToolCallRecordPhase::Requested{owner:OperationOwner::Workflow}}),i as i64);
                if repeats {
                    push(JournalEntry::ToolCallRecorded(ToolCallRecorded{call:call.clone(),
                        phase:ToolCallRecordPhase::Resolved{resolution:ToolCallResolution::Allowed}}),-100);
                    let result=ToolResult::ok(call.id,"fixture");
                    push(JournalEntry::ToolResultRecorded(ToolResultRecorded{result}),-200);
                }
            }
            let projection=JournalProjection::build(session,records).expect("valid synthetic journal prefix");
            let (index,m,end)=crate::w333_alloc::measure(||TranscriptTimestamps::default().collect::<true>(&projection.records));
            let control=TranscriptTimestamps::default().collect::<false>(&projection.records);
            assert_eq!(index.calls.len(),n);
            assert!(index.call("absent").is_none());
            let values:Vec<_>=ids.iter().enumerate().map(|(i,id)|{
                let got=index.call(id);
                assert_eq!(got,Some(i as i64));
                assert_eq!(got,control.call(id));
                (id,got)
            }).collect();
            if let Some(dir)=std::env::var_os("W333_WITNESS_DIR") {
                std::fs::write(std::path::PathBuf::from(dir).join(format!("{n}-{}.json",u8::from(repeats))),
                    serde_json::to_vec(&values).unwrap()).unwrap();
            }
            let size=index.calls.values().next().map_or(0,std::mem::size_of_val);
            eprintln!("W333 {n} {} {size} {} {end}",u8::from(repeats),m.peak);
        }
    }
}
